files.content:
@keyframes up {
  to {
    transform: translateY(50%);
  }
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  min-block-size: 100dvh;
}

.wrapper {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  background:
    linear-gradient(rgb(0 0 0 / 0.2), rgb(0 0 0 / 0.2)),
    url(../images/img.jpg);
  background-size: cover;
  inline-size: 100%;
  max-inline-size: 850px;
  min-block-size: 100dvh;
}

.mix-text {
  position: relative;
  margin: 0;
  color: #d3ffd3;
  font-weight: bold;
  font-size: 18vw;
  transition: 0.3s cubic-bezier(0.25, 0.25, 0.33, 1.33);

  /* напишите код здесь */
  mix-blend-mode: overlay;
}

.wrapper:hover .mix-text {
  animation: up 6s ease-out infinite alternate;
}
